/**
 * `/help/` —— 帮助中心索引
 *
 * 🔴 **本页承担两个角色，删改前都要看**：
 *    ① 平台 help 族的索引（文章数据在 `src/data/help.js`，页面由
 *       `gatsby-node.js` 生成为 `/help/<slug>/`）；
 *    ② **外部登记的那个「Help Center」URL** —— `SHOPIFY_REVIEW_NOTES.md` 登记给
 *       Shopify 审核、Cart 后台产品内入口、App Store 旧链桩三处全部指向 `/help/`。
 *       ⇒ **Cart 入口必须在首屏可见**，否则审核方与 Cart 用户点进来会找不到东西。
 *       Cart 的完整帮助中心已下沉到 `/help/cart/`（内容未改，只改路径）。
 *
 * 🔴 **与 `/guides/` 的分工**（别混，2026-10-13 定）：
 *    `guides` = 讲清一个机制（why / what）；`help` = 做完一件事（how 步骤）。
 *    边界写在 `src/data/help.js` 的文件头。
 *
 * 🔴 `softwareApp={false}`：本页讲 Messaging，不是 Whaleal Cart 那个 Shopify 应用。
 *
 * ⚠️ 本页**不是** i18n 驱动（文案直接写在页里，因为文章内容来自英文数据源）。
 *    因此它**已从 `LOCALIZED_PAGES` 移除** —— 加回 de/fr 时不会把它克隆成
 *    `/de/help/` 一份只有英文的页。
 *
 * @author 恒哥
 * @since 2026-10-13
 */
import React from 'react';
import { Link } from 'gatsby';
import Layout from '../../components/Layout';
import SEO from '../../components/SEO';
import { groupHelpArticles } from '../../data/help';
import { INTEGRATION_STATS } from '../../data/integrations';
import { MESSAGING_CONSOLE_URL, SUPPORT_EMAIL } from '../../constants/brand';
import '../../styles/marketing.css';
import T from '../../i18n/LocalizedText';
import { usePageI18n } from '../../i18n';

export default function HelpIndex(pageContext) {
  const { locale, localePath } = usePageI18n(pageContext);

  const groups = groupHelpArticles();

  return (
    <Layout locale={pageContext?.locale}>
      <SEO
        title="Help center — connect, send and diagnose"
        description="How to connect a provider, send your first message, handle opt-out keywords, read delivery receipts and diagnose messages that are accepted but never arrive."
        pathname="/help/"
        softwareApp={false} hrefLang={locale}
      />
      <div className="mk">
        <header className="mk-hero">
          <span className="mk-eyebrow"><T id="help.001">Help center</T></span>
          <h1><T id="help.002">Help center</T></h1>
          <p className="mk-lead"><T id="help.003">
            Task-level answers: what to configure, in what order, and which failures are silent.
            For the reasoning behind how the platform behaves, the guides go a level deeper.
          </T></p>
        </header>

        {/* 🔴 Cart 入口必须在这里，且靠前 —— 理由见文件头 ②。不要把它挪到页尾。 */}
        <section className="mk-section">
          <h2><T id="help.004">Whaleal Cart</T></h2>
          <p className="mk-section-lead"><T id="help.005">
            Installing the Shopify app, editing recovery emails, tuning send timing, and fixing a
            recovery that did not fire.
          </T></p>
          <div className="mk-grid">
            <article className="mk-card">
              <h3><T id="help.006">Whaleal Cart help center</T></h3>
              <p><T id="help.007">
                Setup walkthrough, templates, plans, troubleshooting and the usual questions — all in
                one page.
              </T></p>
              <Link className="mk-card-link" to={localePath("/help/cart/")}><T id="help.008">
                Open the Cart help center &rarr;
              </T></Link>
            </article>
            <article className="mk-card">
              <h3><T id="help.009">Install Whaleal Cart</T></h3>
              <p><T id="help.010">Enter your store domain to start the Shopify install flow.</T></p>
              <Link className="mk-card-link" to={localePath("/install/")}><T id="help.011">
                Go to the install page &rarr;
              </T></Link>
            </article>
          </div>
        </section>

        {groups.map((group) => (
          <section className="mk-section" key={group.id}>
            <h2>{group.title}</h2>
            <p className="mk-section-lead">{group.blurb}</p>
            <div className="mk-grid">
              {group.articles.map((a) => (
                <article className="mk-card" key={a.slug}>
                  <span className="mk-card-tag"><T id="help.012">{a.readMinutes} min</T></span>
                  <h3>{a.title}</h3>
                  <p>{a.excerpt}</p>
                  <Link className="mk-card-link" to={`/help/${a.slug}/`}><T id="help.013">
                    Read this article &rarr;
                  </T></Link>
                </article>
              ))}
            </div>
          </section>
        ))}

        <div className="mk-scope">
          <T id="help.014"><strong>Scope.</strong> Most articles here walk the SMS channel end to end. Email and
          WhatsApp connect the same way — you link your own provider account and send from the
          console: {INTEGRATION_STATS.byChannel.SMS} providers on SMS,{' '}
          {INTEGRATION_STATS.byChannel.EMAIL} on email and {INTEGRATION_STATS.byChannel.WHATSAPP} on
          WhatsApp. Scheduled and bulk sending run on the SMS channel only, and a provider we do not
          list yet is registered as a request from the console rather than offered as a connection.
        </T></div>

        <section className="mk-section">
          <h2><T id="help.015">Still stuck</T></h2>
          <p className="mk-section-lead"><T id="help.016">
            If a message was accepted and you cannot tell where it went, start with the
            troubleshooting article — it rules out whole layers before you contact the carrier.
          </T></p>
          <div className="mk-actions">
            <Link className="mk-btn mk-btn-secondary" to={localePath("/help/messages-not-arriving/")}><T id="help.017">
              Messages are accepted but not arriving
            </T></Link>
            <a className="mk-btn mk-btn-secondary" href={MESSAGING_CONSOLE_URL} target="_blank" rel="noopener noreferrer"><T id="help.018">
              Open the console
            </T></a>
            <a className="mk-btn mk-btn-secondary" href={`mailto:${SUPPORT_EMAIL}`}><T id="help.019">
              Email support
            </T></a>
          </div>
        </section>
      </div>
    </Layout>
  );
}
